src.fragment:

uniform float uTime;
uniform vec3 uSunDir, uSunCol, uSky, uGnd;
uniform sampler2D uShadow, uNoise;
uniform float uShadowHalf, uDusk, uGlow, uNight;
uniform vec3 uFogOut, uMapShift;
float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
// 1 in sunlight, 0 in a shadow (terrain, buildings), softened over a couple of metres; the
// shadows are the day sun's, so they fade away as night falls (the moon's soft light casts none)
float sunShadow(vec3 w) {
  vec2 uv = w.xz / (2.0 * uShadowHalf) + 0.5;
  if (uNight > 0.999 || uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) return 1.0;
  float top = texture2D(uShadow, uv).r;
  return mix(smoothstep(top - 2.0, top + 1.0, w.y), 1.0, uNight);
}
// the clouds' shadows drifting over everything
float cloudShade(vec2 xz) {
  float c = texture2D(uNoise, xz / 2300.0 + vec2(uTime * 0.0021, uTime * 0.0009)).b;
  return mix(1.0, 0.6, smoothstep(0.52, 0.72, c));
}
vec3 ambient(vec3 n) { return mix(uGnd, uSky, n.y * 0.5 + 0.5); }
// the sky looking along r (what glass and water reflect): warm horizon and the sun's glow by
// day; by night a deep blue zenith over a horizon lit violet by the city, and the moon
vec3 skyCol(vec3 r) {
  float up = clamp(r.y, 0.0, 1.0);
  float toSun = max(dot(normalize(r), uSunDir), 0.0);
  vec3 day = mix(vec3(1.0, 0.82, 0.68), vec3(0.32, 0.5, 0.86), pow(up, 0.55)) + vec3(1.0, 0.7, 0.4) * pow(toSun, 8.0) * 0.8;
  vec3 night = mix(vec3(0.2, 0.12, 0.26), vec3(0.02, 0.035, 0.09), pow(up, 0.4)) + vec3(0.5, 0.6, 0.9) * pow(toSun, 60.0) * 0.5;
  return mix(day, night, uNight);
}
// the light a matte surface with normal n gets at w
vec3 mapLight(vec3 n, vec3 w) {
  float ndl = max(dot(n, uSunDir), 0.0);
  float cs = cloudShade(w.xz);
  // (looked up a few metres out from the surface, so a sunlit wall doesn't shade itself)
  return ambient(n) * mix(0.82, 1.0, cs) + uSunCol * (ndl * sunShadow(w + n * 3.5) * cs);
}


// integral of a pulse train that is on for the first 'duty' of every unit cell
float pulseI(float x, float duty) { return floor(x) * duty + min(fract(x), duty); }
// that pulse train box-filtered over a width w (in cells): its exact average there
float fpulse(float x, float duty, float w) {
  w = max(w, 1e-4);
  return (pulseI(x + 0.5 * w, duty) - pulseI(x - 0.5 * w, duty)) / w;
}
// a band [a, b] box-filtered over a width w
float fband(float x, float a, float b, float w) {
  w = max(w, 1e-4);
  return clamp((min(x + 0.5 * w, b) - max(x - 0.5 * w, a)) / w, 0.0, 1.0);
}


const vec3 R_WHITE = vec3(0.8, 0.8, 0.76);
const vec3 R_YELLOW = vec3(0.86, 0.55, 0.09);
const vec3 R_KERB = vec3(0.6, 0.58, 0.54);
const vec3 R_PAVE = vec3(0.44, 0.41, 0.37);
const vec3 R_GRASS = vec3(0.17, 0.28, 0.07);
const vec3 R_CITY_TAR = vec3(0.058, 0.061, 0.072);
// a line of half width h centred at c, box-filtered over a pixel
float rLine(float x, float c, float h, float px) { return fband(x, c - h, c + h, px); }
// on for 'duty' of every 'period' metres
float rDash(float s, float period, float duty, float px) { return fpulse(s / period, duty, px / period); }
// street lamps: a glimmer by day, full at night
float rLampsOn() { return mix(0.04, 1.0, clamp((uDusk - 0.55) / 0.45, 0.0, 1.0)); }
// a pool of lamp light: ds along, dc across from the lamp, r its reach
float rPool(float ds, float dc, float r) { return exp(-(ds * ds + dc * dc) / (r * r)); }

// a grass verge, with wild flowers in it
vec3 rVerge(vec2 xz, vec4 nz, float px) {
  vec3 c = R_GRASS * (0.78 + 0.45 * nz.g);
  vec2 q = xz * 1.7;
  float h = hash12(floor(q));
  float speck = step(0.84, h) * smoothstep(0.34, 0.18, length(fract(q) - 0.5)) * smoothstep(0.6, 0.2, px);
  vec3 flower = h > 0.95 ? vec3(0.9, 0.85, 0.75) : h > 0.9 ? vec3(0.9, 0.42, 0.55) : vec3(0.95, 0.75, 0.2);
  return mix(c, flower, speck);
}

// paving slabs
vec3 rPave(vec2 xz, vec4 nz, float px) {
  vec3 c = R_PAVE * (0.9 + 0.16 * nz.r);
  return c * (1.0 - 0.14 * max(fpulse(xz.x / 1.4, 0.05, px / 1.4), fpulse(xz.y / 1.4, 0.05, px / 1.4)));
}

// a city avenue's or street's carriageway (kerb to kerb): o across from its centre, s along
vec3 rCityLanes(bool avenue, float o, float s, vec2 px, vec4 nz, float hue, inout vec3 glow) {
  float a = abs(o);
  float hw = avenue ? 10.50 : 6.50;
  vec3 c = R_CITY_TAR * (0.88 + 0.24 * nz.r);
  if (avenue) {
    // the outer lane each way is a terracotta bus lane, behind a solid white line
    c = mix(c, vec3(0.16, 0.066, 0.05) * (0.9 + 0.2 * nz.r), fband(a, 6.15, hw, px.x));
    c = mix(c, R_WHITE, rLine(a, 6.05, 0.1, px.x));
    c *= 1.0 - 0.12 * rLine(a, 3.8, 0.9, px.x);
    // the planted median, kerbed, with a strip of neon along it at night
    vec3 med = mix(R_KERB, vec3(0.07, 0.14, 0.035) * (0.75 + 0.5 * nz.a), fband(a, 0.0, 1.32, px.x));
    c = mix(c, med, fband(a, 0.0, 1.6, px.x));
    vec3 neon = hue < 0.5 ? vec3(0.25, 0.94, 1.0) : vec3(1.0, 0.25, 0.64);
    glow += neon * (2.2 * rLine(a, 1.66, 0.06, px.x) + 0.1 * smoothstep(3.4, 1.7, a) * step(1.6, a)) * uNight * uGlow * 0.45;
  } else {
    // parking bays along both kerbs, a dashed line down the middle
    float bay = fband(a, 4.3, hw, px.x);
    c = mix(c, c * 1.4, bay);
    c = mix(c, R_WHITE * 0.8, bay * rDash(s, 6.0, 0.025, px.y) + rLine(a, 4.3, 0.06, px.x));
    c = mix(c, vec3(0.75, 0.68, 0.48), rLine(a, 0.0, 0.08, px.x) * rDash(s, 9.0, 0.45, px.y));
  }
  // the gutter along the kerb
  return c * (1.0 - 0.3 * fband(a, hw - 0.35, hw, px.x));
}

// any road's surface right across (verges or pavements included). kind: see Kind in roadnet.ts
vec3 roadColor(float kind, float o, float s, float hw, vec2 px, vec4 nz, vec4 nz2, vec2 xz, inout vec3 glow) {
  int k = int(kind + 0.5);
  float a = abs(o);
  vec3 c;
  if (k == 0) {
    // the expressway: two lanes each way, hard shoulders, a concrete median with lamps down it
    c = vec3(0.045, 0.05, 0.06) * (0.92 + 0.14 * nz.r);
    c *= 1.0 - 0.13 * (rLine(a, 3.3, 0.8, px.x) + rLine(a, 6.85, 0.8, px.x));
    c = mix(c, c * 1.45 + 0.01, fband(a, 8.95, hw, px.x));
    c = mix(c, R_WHITE, rLine(a, 5.08, 0.09, px.x) * rDash(s, 18.0, 0.33, px.y));
    c = mix(c, R_WHITE, rLine(a, 8.82, 0.13, px.x));
    c = mix(c, R_YELLOW, rLine(a, 1.6, 0.1, px.x));
    c = mix(c, vec3(0.36, 0.35, 0.33) * (0.9 + 0.2 * nz.r), fband(a, 0.0, 1.35, px.x));
    c = mix(c, rVerge(xz, nz, px.x), fband(a, hw, 99.0, px.x));
    float ds = (fract(s / 40.0 + 0.5) - 0.5) * 40.0;
    glow += vec3(0.62, 0.86, 1.0) * rPool(ds, a - 5.0, 5.0) * 0.36 * rLampsOn() * step(a, hw + 0.5);
  } else if (k == 1) {
    // a country road: patched asphalt, white edges, a dashed white centre line, gravel shoulders
    c = vec3(0.09, 0.085, 0.078) * (0.9 + 0.18 * nz.r);
    c *= mix(1.0, 0.8, smoothstep(0.62, 0.66, nz2.a));
    c = mix(c, R_WHITE, rLine(a, 0.0, 0.07, px.x) * rDash(s, 12.0, 0.25, px.y));
    c = mix(c, R_WHITE, rLine(a, hw - 0.3, 0.08, px.x));
    c = mix(c, vec3(0.36, 0.31, 0.24) * (0.8 + 0.4 * nz.r), fband(a, hw, 99.0, px.x));
  } else if (k == 2) {
    // the mountain road: narrower, weathered, a double yellow line, stone chippings at the side
    c = vec3(0.068, 0.064, 0.06) * (0.88 + 0.24 * nz.r);
    c *= mix(1.0, 0.82, smoothstep(0.6, 0.64, nz2.a));
    c = mix(c, R_YELLOW, fband(a, 0.07, 0.19, px.x));
    c = mix(c, R_WHITE, rLine(a, hw - 0.22, 0.07, px.x));
    c = mix(c, vec3(0.3, 0.29, 0.27) * (0.8 + 0.4 * nz.r), fband(a, hw, 99.0, px.x));
  } else if (k == 3) {
    // a village lane: pale old asphalt, ragged edges into flowery verges, a lamp now and then
    c = vec3(0.15, 0.14, 0.125) * (0.82 + 0.34 * nz.r);
    c = mix(c, R_GRASS * 0.9, 0.3 * smoothstep(0.5, 0.0, a) * nz.a);
    c = mix(c, rVerge(xz, nz, px.x), fband(a, hw - 0.4 * nz.g, 99.0, px.x));
    float ds = (fract(s / 32.0 + 0.5) - 0.5) * 32.0;
    glow += vec3(1.0, 0.66, 0.34) * rPool(ds, o - hw, 5.0) * 0.5 * rLampsOn();
  } else if (k == 4) {
    // a farm track: two dusty ruts and a strip of grass down the middle
    c = vec3(0.34, 0.25, 0.15) * (0.82 + 0.34 * nz.r);
    c *= 1.0 - 0.22 * rLine(a, 0.85, 0.28, px.x);
    c = mix(c, R_GRASS * (0.9 + 0.3 * nz.g), fband(a, 0.0, 0.3 + 0.12 * nz.g, px.x));
    c = mix(c, rVerge(xz, nz, px.x), fband(a, hw - 0.25 * nz.g, 99.0, px.x));
  } else if (k == 7) {
    // an alley: stone setts, a gutter down the middle, paper lanterns strung across at night
    vec2 q = vec2(s / 0.55, o / 0.4);
    q.x += 0.5 * mod(floor(q.y), 2.0);
    float id = mix(hash12(floor(q) + 3.0), 0.5, smoothstep(0.08, 0.3, max(px.x, px.y)));
    c = vec3(0.42, 0.34, 0.29) * (0.78 + 0.4 * id);
    c *= 1.0 - 0.4 * max(fpulse(q.x, 0.1, px.y / 0.55), fpulse(q.y, 0.12, px.x / 0.4));
    c *= 1.0 - 0.4 * rLine(a, 0.0, 0.16, px.x);
    float ds = (fract(s / 5.0 + 0.5) - 0.5) * 5.0;
    glow += vec3(1.0, 0.42, 0.22) * (0.1 + 0.45 * rPool(ds, a - 1.2, 2.2)) * rLampsOn();
  } else {
    // a city avenue or street carried over a bridge
    bool av = k == 5;
    float chw = av ? 10.50 : 6.50;
    vec3 g = vec3(0.0);
    c = rCityLanes(av, o, s, px, nz, 0.0, g);
    glow += g * step(a, chw);
    c = mix(c, rPave(xz, nz, px.x), fband(a, chw, 99.0, px.x));
    c = mix(c, R_KERB, fband(a, chw, chw + 0.3, px.x));
  }
  return c;
}

    uniform vec4 uGrid;
    uniform vec2 uStreet;
    uniform vec4 uLines[LINES];
    uniform vec4 uLineK;
    varying vec3 vCol, vN, vWorld, vMask;
    #include <fog_pars_fragment>

    // the grid line nearest p (q along it): offset from it, its half width (0: no street here),
    // how far q is past its ends, and avenue + 2 * neon colour
    vec4 gridLine(float p, float q, float origin, float k0, float base, float count) {
      float k = floor((p - origin) / uGrid.z + 0.5);
      float o = p - (origin + k * uGrid.z);
      float i = k - k0;
      if (i < 0.0 || i > count - 0.5) return vec4(o, 0.0, 1e4, 0.0);
      vec4 L = uLines[int(base + i + 0.5)];
      if (L.y <= L.x) return vec4(o, 0.0, 1e4, 0.0);
      return vec4(o, L.z > 0.5 ? uStreet.y : uStreet.x, max(L.x - q, q - L.y), L.z + 2.0 * L.w);
    }
    // signed distance to that street's carriageway (a long box, square-ended)
    float lineSD(vec4 g) {
      if (g.y <= 0.0) return 1e4;
      vec2 q = vec2(abs(g.x) - g.y, g.z);
      return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);
    }

    void main() {
      vec3 base = vCol;
      vec3 w = vWorld;
      vec4 nz = texture2D(uNoise, w.xz / 37.0);
      vec4 nz2 = texture2D(uNoise, w.xz / 420.0);
      vec2 pxy = fwidth(w.xz);
      float px = length(pxy);
      float mx = fwidth(vMask.x) + 1e-4, mz = fwidth(vMask.z) + 1e-4;
      // grain and mottling everywhere
      base *= 0.88 + 0.16 * nz.r + 0.12 * (nz2.g - 0.5);
      vec3 glow = vec3(0.0);

      // patchwork fields: crops in tilted plots with furrows and hedgerows between
      if (vMask.y > 0.02) {
        vec2 q = mat2(0.94, -0.34, 0.34, 0.94) * w.xz;
        vec2 cell = floor(q / vec2(46.0, 31.0));
        vec2 f = fract(q / vec2(46.0, 31.0));
        float hc = hash12(cell + 7.0);
        vec3 crop = hc < 0.22 ? vec3(0.62, 0.45, 0.12) : hc < 0.45 ? vec3(0.25, 0.42, 0.1) : hc < 0.62 ? vec3(0.42, 0.52, 0.16) : hc < 0.78 ? vec3(0.42, 0.28, 0.16) : hc < 0.88 ? vec3(0.36, 0.3, 0.5) : vec3(0.56, 0.5, 0.18);
        float rows = 0.92 + 0.08 * sin((hc > 0.5 ? q.x : q.y) * 2.4);
        crop *= rows * (0.9 + 0.2 * nz.a);
        vec2 e = min(f, 1.0 - f) * vec2(46.0, 31.0);
        float hedge = 1.0 - smoothstep(0.8, 1.8 + px, min(e.x, e.y));
        crop = mix(crop, vec3(0.1, 0.2, 0.06), hedge * 0.85);
        base = mix(base, crop, vMask.y);
      }

      // the city: paved to a crisp edge (a line of kerbstones where it meets the grass), parks
      // hedged round, and the street grid
      float cityIn = (vMask.x - 0.5 + 0.08 * (nz2.b - 0.5)) / mx * px;
      float park = clamp((vMask.z - 0.5) / mz + 0.5, 0.0, 1.0);
      if (vMask.x > 0.3) {
        vec3 paving = vec3(0.38, 0.33, 0.27) * (0.86 + 0.2 * nz.r + 0.1 * (nz2.g - 0.5));
        float paved = fband(cityIn, 0.0, 1e4, px) * (1.0 - park);
        base = mix(base, paving, paved);
        base = mix(base, R_KERB * 0.9, fband(cityIn, 0.0, 0.35, px) * (1.0 - park));
        base = mix(base, vec3(0.1, 0.2, 0.05), fband((vMask.z - 0.5) / mz * px, -0.6, 0.0, px) * step(0.3, vMask.x));
      }
      vec4 gx = gridLine(w.x, w.z, uGrid.x, uLineK.x, 0.0, uLineK.z);
      vec4 gz = gridLine(w.z, w.x, uGrid.y, uLineK.y, uLineK.z, uLineK.w);
      float d1 = lineSD(gx), d2 = lineSD(gz);
      // (streets stay on the city's plain, never down the river banks or onto the beach)
      if (min(d1, d2) < 3.5 && w.y > uGrid.w - 0.9) {
        // the carriageways, their kerbs rounded at the corners
        const float R = 4.0;
        float sd = max(R, min(d1, d2)) - length(max(vec2(R - d1, R - d2), 0.0));
        bool onX = d1 < d2;
        vec4 g = onX ? gx : gz, x2 = onX ? gz : gx;
        float o = g.x, s = onX ? w.z : w.x, a = abs(o);
        vec2 pa = onX ? pxy : pxy.yx;
        bool av = mod(g.w, 2.0) > 0.5;
        float hw = g.y;
        vec3 lg = vec3(0.0);
        vec3 road = rCityLanes(av, o, s, pa, nz, floor(g.w / 2.0), lg);
        float e = abs(x2.x) - x2.y;
        if (x2.y > 0.0 && x2.z <= 0.0) {
          if (e < 0.0 && a < hw) {
            // in the junction: plain tarmac, and where two avenues cross, a scramble crossing
            road = R_CITY_TAR * (0.88 + 0.24 * nz.r);
            lg = vec3(0.0);
            if (av && mod(x2.w, 2.0) > 0.5) {
              float u = abs(gx.x), v = abs(gz.x);
              float diag = fband(u - v, -1.6, 1.6, px) * fpulse((u + v) / 1.3, 0.5, px * 1.5 / 1.3) * step(2.5, u + v);
              road = mix(road, R_WHITE * 0.92, diag);
            }
          } else if (e >= 0.0) {
            // zebra crossings just past the junction, stop lines behind them
            float lanes = av ? fband(a, 1.7, hw - 0.2, pa.x) : fband(a, -1.0, hw - 0.2, pa.x);
            float zebra = fband(e, 0.8, 3.8, pa.y) * fpulse(o / 1.1 + 0.25, 0.5, pa.x / 1.1);
            float stop = fband(e, 4.3, 4.75, pa.y) * step(0.0, (onX ? 1.0 : -1.0) * o * x2.x);
            road = mix(road, R_WHITE * 0.9, (zebra + stop) * lanes);
          }
        }
        vec3 c = mix(base, rPave(w.xz, nz, px), fband(min(d1, d2), -1e4, 3.0, px) * (1.0 - park));
        c = mix(c, road * (1.0 - 0.3 * fband(sd, -0.35, 0.0, px)), fband(sd, -1e4, 0.0, px));
        c = mix(c, R_KERB, fband(sd, 0.0, 0.3, px));
        base = c;
        glow += lg * fband(sd, -1e4, 0.0, px);
        // street lamps: warm pools of light along the kerbs (sodium, the odd white one), where
        // the lamps stand (every 22 m, 1.5 m out from the kerb)
        float k22 = floor((s - 11.0) / 22.0 + 0.5);
        float ds = s - (k22 * 22.0 + 11.0);
        float side = o < 0.0 ? -1.0 : 1.0;
        vec2 lp = onX ? vec2(w.x - o + side * (hw + 1.5), k22 * 22.0 + 11.0) : vec2(k22 * 22.0 + 11.0, w.z - o + side * (hw + 1.5));
        vec3 lc = fract(sin(dot(lp, vec2(12.9, 78.2))) * 43758.5) < 0.3 ? vec3(0.8, 0.9, 1.0) : vec3(1.0, 0.62, 0.3);
        glow += lc * rPool(ds, a - hw - 1.5, 3.2) * 0.4 * rLampsOn() * (1.0 - park) * step(g.z, 0.0);
      }

      // wet sand at the water's edge
      base *= mix(0.78, 1.0, smoothstep(0.15, 0.9, w.y));
      vec3 c = base * mapLight(normalize(vN), w) + glow;
      gl_FragColor = vec4(c, 1.0);

#include <tonemapping_fragment>
#include <colorspace_fragment>
#ifdef USE_FOG
  gl_FragColor.rgb = mix(gl_FragColor.rgb, uFogOut, 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth));
#endif

    }

