src.fragment:

uniform float uTime;
uniform vec3 uSunDir, uSunCol, uSky, uGnd;
uniform sampler2D uShadow, uNoise;
uniform float uShadowHalf, uDusk, uGlow, uNight;
uniform vec3 uFogOut, uMapShift;
float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
// 1 in sunlight, 0 in a shadow (terrain, buildings), softened over a couple of metres; the
// shadows are the day sun's, so they fade away as night falls (the moon's soft light casts none)
float sunShadow(vec3 w) {
  vec2 uv = w.xz / (2.0 * uShadowHalf) + 0.5;
  if (uNight > 0.999 || uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) return 1.0;
  float top = texture2D(uShadow, uv).r;
  return mix(smoothstep(top - 2.0, top + 1.0, w.y), 1.0, uNight);
}
// the clouds' shadows drifting over everything
float cloudShade(vec2 xz) {
  float c = texture2D(uNoise, xz / 2300.0 + vec2(uTime * 0.0021, uTime * 0.0009)).b;
  return mix(1.0, 0.6, smoothstep(0.52, 0.72, c));
}
vec3 ambient(vec3 n) { return mix(uGnd, uSky, n.y * 0.5 + 0.5); }
// the sky looking along r (what glass and water reflect): warm horizon and the sun's glow by
// day; by night a deep blue zenith over a horizon lit violet by the city, and the moon
vec3 skyCol(vec3 r) {
  float up = clamp(r.y, 0.0, 1.0);
  float toSun = max(dot(normalize(r), uSunDir), 0.0);
  vec3 day = mix(vec3(1.0, 0.82, 0.68), vec3(0.32, 0.5, 0.86), pow(up, 0.55)) + vec3(1.0, 0.7, 0.4) * pow(toSun, 8.0) * 0.8;
  vec3 night = mix(vec3(0.2, 0.12, 0.26), vec3(0.02, 0.035, 0.09), pow(up, 0.4)) + vec3(0.5, 0.6, 0.9) * pow(toSun, 60.0) * 0.5;
  return mix(day, night, uNight);
}
// the light a matte surface with normal n gets at w
vec3 mapLight(vec3 n, vec3 w) {
  float ndl = max(dot(n, uSunDir), 0.0);
  float cs = cloudShade(w.xz);
  // (looked up a few metres out from the surface, so a sunlit wall doesn't shade itself)
  return ambient(n) * mix(0.82, 1.0, cs) + uSunCol * (ndl * sunShadow(w + n * 3.5) * cs);
}


vec3 skyRefl(vec3 r) {
  return skyCol(r);
}
// a wave normal from two scrolling noise layers
vec3 waveN(vec2 xz, float k) {
  vec2 a = texture2D(uNoise, xz / 61.0 + vec2(uTime * 0.011, uTime * 0.007)).rg;
  vec2 b = texture2D(uNoise, xz / 23.0 - vec2(uTime * 0.017, -uTime * 0.012)).rg;
  vec2 g = (a - 0.5) * 0.9 + (b - 0.5) * 0.7;
  return normalize(vec3(g.x * k, 1.0, g.y * k));
}


uniform sampler2D uDepth;
uniform float uFine;
uniform vec4 uMouth;
vec3 seaColor(vec3 w, float minD) {
  vec2 uv = w.xz / (2.0 * uFine) + 0.5;
  float inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
  vec4 dm = texture2D(uDepth, clamp(uv, 0.0, 1.0));
  // depth 0 (shore) .. 1 (24 m and more)
  float d = max(mix(1.0, dm.r, inside), minD);
  vec3 V = normalize((cameraPosition - uMapShift) - w);
  float px = length(fwidth(w.xz));
  // calmer, smoother water far off (and no shimmering ripples smaller than a pixel)
  vec3 n = waveN(w.xz, mix(0.5, 0.05, smoothstep(2.0, 18.0, px)));
  float shade = cloudShade(w.xz);
  // the colour of the water itself: clear turquoise over the sand, deep blue further out
  vec3 shallow = vec3(0.18, 0.72, 0.68);
  vec3 mid = vec3(0.05, 0.38, 0.52);
  vec3 deep = vec3(0.02, 0.14, 0.3);
  vec3 body = mix(shallow, mid, smoothstep(0.0, 0.25, d));
  body = mix(body, deep, smoothstep(0.25, 1.0, d));
  // sand and reef showing through the shallows
  float reef = texture2D(uNoise, w.xz / 90.0).a;
  body = mix(body, vec3(0.55, 0.7, 0.5), (1.0 - smoothstep(0.0, 0.1, d)) * 0.45);
  body *= mix(1.0, 0.82 + 0.3 * reef, (1.0 - smoothstep(0.02, 0.2, d)) * 0.6);
  // the river's plume: its greener, cloudier water fanning out past the mouth and fading into
  // the sea, ragged at the edges, carried out on the current
  vec2 mp = w.xz - uMouth.xy;
  float al = dot(mp, uMouth.zw), ac = dot(mp, vec2(-uMouth.w, uMouth.z));
  vec4 pn = texture2D(uNoise, vec2(ac / 200.0, (al - uTime * 2.2) / 420.0));
  float spread = 45.0 + max(al, 0.0) * 0.55;
  float plume = smoothstep(spread, spread * 0.3, abs(ac) + (pn.g - 0.5) * 70.0) * smoothstep(-90.0, -30.0, al);
  plume *= 1.0 - smoothstep(110.0, 320.0, al + (pn.b - 0.5) * 120.0);
  vec4 pf = texture2D(uNoise, vec2(ac / 300.0, (al - uTime * 2.2) / 600.0));
  body = mix(body, mix(vec3(0.09, 0.36, 0.33), vec3(0.2, 0.42, 0.34), smoothstep(0.2, 0.8, pf.b)), plume * mix(0.65, 0.3, smoothstep(0.0, 300.0, al)));
  body *= ambient(vec3(0.0, 1.0, 0.0)) * 1.15 + uSunCol * 0.35 * uSunDir.y * shade;
  // the sky reflected (more of it at grazing angles)
  vec3 r = reflect(-V, n);
  float fres = 0.04 + 0.96 * pow(1.0 - max(dot(V, n), 0.0), 5.0);
  vec3 c = mix(body, skyRefl(r) * mix(0.75, 1.0, shade), clamp(fres, 0.0, 1.0) * 0.85);
  // the sun's path: a broad sheen and the glitter in it
  float sd = max(dot(r, uSunDir), 0.0);
  c += uSunCol * (pow(sd, 90.0) * 0.6 + pow(sd, 900.0) * 6.0) * shade;
  // surf: bands rolling in to every shore, breaking into foam at the water's edge (calmed where
  // the river's current runs out against it)
  float shore = 1.0 - smoothstep(0.0, 0.07, d);
  float band = sin(d * 260.0 - uTime * 1.6 + reef * 6.0);
  float foam = shore * smoothstep(0.55, 0.95, band) * (0.5 + 0.5 * texture2D(uNoise, w.xz / 9.0 + uTime * 0.02).r) * (1.0 - plume * 0.7);
  foam = max(foam, 1.0 - smoothstep(0.0, 0.012, d - 0.002 * sin(uTime * 1.3 + w.x * 0.05)));
  return mix(c, vec3(0.96, 0.97, 0.95) * (ambient(vec3(0.0, 1.0, 0.0)) + uSunCol * 0.45 * shade), clamp(foam, 0.0, 1.0) * inside * 0.9);
}

    uniform vec2 uMouthS;
    varying vec3 vWorld;
    varying vec4 vFlow, vBed;
    #include <fog_pars_fragment>
    // The pattern on the water carried downstream at vel (m/s), through flow space p (metres
    // across, metres along). Two copies slide along and cross-fade, each starting over every
    // couple of seconds from a fresh spot, so water running fast mid-channel and slow by the banks
    // never drags the pattern out into smears however long the map is open.
    vec4 drift(vec2 p, float vel, vec2 scale, float seed) {
      const float RATE = 0.45;
      float t = uTime * RATE + seed;
      float f0 = fract(t), f1 = fract(t + 0.5);
      vec4 a = texture2D(uNoise, (p - vec2(0.0, f0 * vel / RATE)) * scale + floor(t) * vec2(0.37, 0.61));
      vec4 b = texture2D(uNoise, (p - vec2(0.0, f1 * vel / RATE)) * scale + floor(t + 0.5) * vec2(0.71, 0.29) + 0.5);
      float k = abs(1.0 - 2.0 * f0);
      // (the blend of two loses contrast mid-way; stretched back so it doesn't pulse)
      return (mix(a, b, k) - 0.5) * inversesqrt(k * k + (1.0 - k) * (1.0 - k)) + 0.5;
    }
    void main() {
      vec3 w = vWorld;
      vec3 V = normalize((cameraPosition - uMapShift) - w);
      vec2 dir = normalize(vBed.xy);
      vec3 along = vec3(dir.x, 0.0, dir.y), across = vec3(-dir.y, 0.0, dir.x);
      float d = max(vBed.z, 0.0);
      float speed = vFlow.z, fall = vFlow.w, churn = vBed.w;
      // (ripples smaller than a pixel would only shimmer)
      float lod = 1.0 - smoothstep(1.5, 12.0, length(fwidth(w.xz)));
      // the current: fastest down the deep middle, held back over the shallows
      float vel = speed * 3.2 * mix(0.35, 1.0, smoothstep(0.2, 2.0, d));
      vec2 p = vFlow.yx;
      // (long swirls a few metres across, and the fine chop on them drawn out down the current)
      vec4 big = drift(p, vel, vec2(1.0 / 90.0, 1.0 / 200.0), 0.0);
      vec4 fine = drift(p, vel * 1.15, vec2(1.0 / 24.0, 1.0 / 150.0), 0.37);
      // a slow pattern that stays put: the stones on the bed, and the standing waves over them
      vec4 still = texture2D(uNoise, w.xz / 80.0 + uTime * vec2(0.002, 0.0013));
      float rapid = smoothstep(1.3, 3.8, speed) * (1.0 - fall);
      vec2 g = (big.rg - 0.5) * vec2(1.3, 0.8) + (fine.rg - 0.5) * 0.8;
      g.y += cos(vFlow.x * 0.6 + still.g * 8.0) * 0.4 * rapid;
      vec3 n = normalize(vec3(0.0, 1.0, 0.0) + (across * g.x + along * g.y) * (0.3 + 0.55 * rapid + 0.5 * churn) * lod);
      // light: the valley walls' shadows and the clouds' fall across it
      float sun = sunShadow(w + vec3(0.0, 1.0, 0.0)) * cloudShade(w.xz);
      vec3 amb = ambient(vec3(0.0, 1.0, 0.0));
      // the water itself: glacial teal down the deep channel, clear green over the shallows, the
      // stony bed showing through near the banks with the sun's caustics rippling over it
      vec3 body = mix(vec3(0.12, 0.42, 0.38), vec3(0.025, 0.17, 0.22), smoothstep(0.2, 2.6, d));
      float clear = exp(-d * 1.2);
      body = mix(body, vec3(0.46, 0.42, 0.33) * (0.7 + 0.6 * still.a), clear * 0.7);
      body *= amb * 1.15 + uSunCol * 0.4 * sun;
      float caus = 1.0 - smoothstep(0.0, 0.035, abs(fine.r - still.r));
      body += uSunCol * caus * clear * clear * 0.3 * sun * lod;
      // the sky in it, the sun's highlight, and glitter carried off down the current
      vec3 r = reflect(-V, n);
      float fres = 0.02 + 0.98 * pow(1.0 - max(dot(V, n), 0.0), 5.0);
      vec3 c = mix(body, skyRefl(r) * mix(0.7, 1.0, sun), clamp(fres, 0.0, 1.0) * 0.85);
      float sd = max(dot(r, uSunDir), 0.0);
      c += uSunCol * (pow(sd, 70.0) * 0.3 + pow(sd, 600.0) * 4.0) * sun;
      c += uSunCol * smoothstep(0.8, 0.96, fine.a) * pow(sd, 12.0) * 2.5 * sun * lod;
      // foam
      vec3 white = vec3(0.93, 0.96, 1.0) * (amb * 1.1 + uSunCol * 0.55 * sun);
      float fn = big.a * 0.6 + fine.a * 0.4;
      // lace along the banks where the current tears at the shallows (on still water, a thin line
      // lapping in and out at the shore)
      float run = min(speed, 1.0);
      float edge = 1.0 - smoothstep(0.0, mix(0.15, 0.8, run), d + (1.0 - run) * 0.08 * sin(uTime * 1.3 + still.g * 12.0));
      float foam = edge * smoothstep(0.55, 0.8, fn + edge * 0.3) * mix(0.35, 0.8, run);
      // bubbles riding the current in long lines; whitecaps all over the rapids
      float moving = smoothstep(0.5, 1.2, speed);
      foam = max(foam, smoothstep(0.66, 0.84, fine.a) * 0.35 * moving * (1.0 - rapid));
      foam = max(foam, smoothstep(0.7 - 0.25 * rapid, 0.9 - 0.15 * rapid, fn) * (0.25 + 0.75 * rapid) * moving);
      // the water boiling white below a fall, breaking up as it drifts on downstream
      float boil = churn * (1.0 - fall);
      foam = max(foam, boil * smoothstep(0.6 - boil * 0.5, 0.85 - boil * 0.3, fn));
      c = mix(c, white * (0.85 + 0.15 * fine.g), clamp(foam, 0.0, 1.0) * 0.92);
      // over a fall: ropes of white water pouring down, with glimpses of the dark water between,
      // lit by how the face of the fall itself turns to the sun
      vec3 face = normalize(cross(dFdx(w), dFdy(w)));
      face *= sign(face.y + 1e-4);
      vec3 lit = vec3(0.93, 0.96, 1.0) * (ambient(face) * 1.15 + uSunCol * 0.6 * max(dot(face, uSunDir), 0.0) * sun);
      vec4 rope = texture2D(uNoise, vec2(vFlow.y / 22.0, vFlow.x / 70.0 - uTime * 0.38));
      float wf = clamp(fall * 1.15, 0.0, 1.0);
      float sheet = mix(0.55, 1.08, smoothstep(0.25, 0.7, rope.g * 0.7 + rope.r * 0.3)) * (0.85 + 0.15 * fine.a);
      float pour = smoothstep(0.3, 0.6, rope.g * 0.5 + fn * 0.5 + (wf - 0.9) * 2.0);
      c = mix(c, lit * sheet, wf * mix(smoothstep(0.35, 0.6, fn), 1.0, wf) * mix(0.5, 1.0, pour));
      // the last stretch turns into the sea, so by where it meets it they're one and the same
      float toSea = smoothstep(uMouthS.x, uMouthS.y, vFlow.x);
      if (toSea > 0.0) c = mix(c, seaColor(w, 0.07), toSea);
      gl_FragColor = vec4(c, 1.0);

#include <tonemapping_fragment>
#include <colorspace_fragment>
#ifdef USE_FOG
  gl_FragColor.rgb = mix(gl_FragColor.rgb, uFogOut, 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth));
#endif

    }

src.vertex:
attribute vec3 aSize;
attribute vec4 aInfo;
attribute float aNeon;
varying vec3 vWorld, vN, vCol;
varying vec2 vFace;
// (per building and per face: flat, so the window hashes see exactly the same numbers
// across a face; interpolated, they drift in the last bits and windows sparkle)
flat varying vec3 vSize;
flat varying vec4 vInfo;
flat varying float vNeon, vFaceW, vFaceId;
#include <fog_pars_vertex>
uniform vec3 uMapShift;
void main() {
  vec4 w = modelMatrix * instanceMatrix * vec4(position, 1.0);
  vWorld = w.xyz - uMapShift;
  vN = normal;
  vCol = instanceColor;
  vSize = aSize;
  vInfo = aInfo;
  vNeon = aNeon;
  // metres across the face from its corner, and up it from the base
  vec3 m = (position + vec3(0.5, 0.0, 0.5)) * aSize;
  bool sx = abs(normal.x) > 0.5;
  vFace = normal.y > 0.5 ? m.xz : vec2(sx ? m.z : m.x, m.y);
  vFaceW = sx ? aSize.z : aSize.x;
  vFaceId = dot(normal, vec3(1.0, 2.0, 3.0));
  vec4 mvPosition = viewMatrix * w;
  gl_Position = projectionMatrix * mvPosition;
  #include <fog_vertex>
}

src.fragment:

uniform float uTime;
uniform vec3 uSunDir, uSunCol, uSky, uGnd;
uniform sampler2D uShadow, uNoise;
uniform float uShadowHalf, uDusk, uGlow, uNight;
uniform vec3 uFogOut, uMapShift;
float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
// 1 in sunlight, 0 in a shadow (terrain, buildings), softened over a couple of metres; the
// shadows are the day sun's, so they fade away as night falls (the moon's soft light casts none)
float sunShadow(vec3 w) {
  vec2 uv = w.xz / (2.0 * uShadowHalf) + 0.5;
  if (uNight > 0.999 || uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) return 1.0;
  float top = texture2D(uShadow, uv).r;
  return mix(smoothstep(top - 2.0, top + 1.0, w.y), 1.0, uNight);
}
// the clouds' shadows drifting over everything
float cloudShade(vec2 xz) {
  float c = texture2D(uNoise, xz / 2300.0 + vec2(uTime * 0.0021, uTime * 0.0009)).b;
  return mix(1.0, 0.6, smoothstep(0.52, 0.72, c));
}
vec3 ambient(vec3 n) { return mix(uGnd, uSky, n.y * 0.5 + 0.5); }
// the sky looking along r (what glass and water reflect): warm horizon and the sun's glow by
// day; by night a deep blue zenith over a horizon lit violet by the city, and the moon
vec3 skyCol(vec3 r) {
  float up = clamp(r.y, 0.0, 1.0);
  float toSun = max(dot(normalize(r), uSunDir), 0.0);
  vec3 day = mix(vec3(1.0, 0.82, 0.68), vec3(0.32, 0.5, 0.86), pow(up, 0.55)) + vec3(1.0, 0.7, 0.4) * pow(toSun, 8.0) * 0.8;
  vec3 night = mix(vec3(0.2, 0.12, 0.26), vec3(0.02, 0.035, 0.09), pow(up, 0.4)) + vec3(0.5, 0.6, 0.9) * pow(toSun, 60.0) * 0.5;
  return mix(day, night, uNight);
}
// the light a matte surface with normal n gets at w
vec3 mapLight(vec3 n, vec3 w) {
  float ndl = max(dot(n, uSunDir), 0.0);
  float cs = cloudShade(w.xz);
  // (looked up a few metres out from the surface, so a sunlit wall doesn't shade itself)
  return ambient(n) * mix(0.82, 1.0, cs) + uSunCol * (ndl * sunShadow(w + n * 3.5) * cs);
}


// integral of a pulse train that is on for the first 'duty' of every unit cell
float pulseI(float x, float duty) { return floor(x) * duty + min(fract(x), duty); }
// that pulse train box-filtered over a width w (in cells): its exact average there
float fpulse(float x, float duty, float w) {
  w = max(w, 1e-4);
  return (pulseI(x + 0.5 * w, duty) - pulseI(x - 0.5 * w, duty)) / w;
}
// a band [a, b] box-filtered over a width w
float fband(float x, float a, float b, float w) {
  w = max(w, 1e-4);
  return clamp((min(x + 0.5 * w, b) - max(x - 0.5 * w, a)) / w, 0.0, 1.0);
}


vec3 skyRefl(vec3 r) {
  // below the horizon: the city across the street
  return mix(vec3(0.16, 0.16, 0.2) * (1.0 - 0.7 * uNight), skyCol(r), smoothstep(-0.12, 0.04, r.y));
}

    uniform vec3 uNeon[5];
    varying vec3 vWorld, vN, vCol;
    varying vec2 vFace;
    // (per building and per face: flat, so the window hashes see exactly the same numbers
    // across a face; interpolated, they drift in the last bits and windows sparkle)
    flat varying vec3 vSize;
    flat varying vec4 vInfo;
    flat varying float vNeon, vFaceW, vFaceId;
    #include <fog_pars_fragment>

    void main() {
      vec3 n = normalize(vN);
      vec3 w = vWorld;
      float style = vInfo.x, seed = vInfo.y, lit = vInfo.z, roof = vInfo.w;
      vec2 f = vFace;
      vec2 px = max(fwidth(f), vec2(1e-3));
      vec4 nz = texture2D(uNoise, (w.xz + w.y) / 23.0);
      vec3 V = normalize((cameraPosition - uMapShift) - w);
      vec3 alb = vCol * (0.93 + 0.12 * nz.r);
      vec3 emit = vec3(0.0);
      float spec = 0.0;
      vec3 neonCol = vNeon >= 0.0 ? uNeon[int(vNeon + 0.5)] : vec3(0.0);

      if (n.y > 0.5) {
        // ---- roofs: gravel, a garden, or a deck with a helipad; a parapet round the edge
        vec2 e = min(f, vSize.xz - f);
        float edge = min(e.x, e.y);
        vec3 r = vec3(0.5, 0.49, 0.47) * (0.85 + 0.25 * nz.g);
        if (roof > 0.5 && roof < 1.5) {
          r = mix(vec3(0.28, 0.45, 0.17), vec3(0.42, 0.55, 0.2), nz.a) * (0.8 + 0.3 * texture2D(uNoise, w.xz / 4.0).r);
          // planters in rows
          r *= 0.85 + 0.15 * fpulse(f.x / 3.0, 0.6, px.x / 3.0);
        } else if (roof > 1.5) {
          r = vec3(0.2, 0.21, 0.23);
          vec2 c = f - vSize.xz * 0.5;
          float d = length(c);
          float rr = min(vSize.x, vSize.z) * 0.32;
          float ring = fband(d, rr - 0.7, rr, length(px));
          float hh = fband(abs(c.x), rr * 0.25, rr * 0.38, px.x) * fband(abs(c.y), 0.0, rr * 0.5, px.y) + fband(abs(c.y), 0.0, 0.35, px.y) * fband(abs(c.x), 0.0, rr * 0.3, px.x);
          r = mix(r, vec3(0.95, 0.75, 0.2), max(ring, hh));
          emit += vec3(1.0, 0.6, 0.25) * ring * uDusk * 0.6;
        }
        // the parapet
        r = mix(r, vCol * 0.85, fband(edge, 0.0, 0.6, length(px)));
        alb = r;
      } else if (style > 4.5) {
        // ---- rooftop kit: louvred metal
        alb = vec3(0.62, 0.63, 0.61) * (0.8 + 0.2 * fpulse(f.y / 0.5, 0.5, px.y / 0.5));
      } else if (style > 3.5) {
        // ---- sheds and containers: corrugated sheet, a roller door on some faces
        alb *= 0.82 + 0.18 * fpulse(f.x / 0.6, 0.5, px.x / 0.6);
        float door = step(0.6, fract(seed * 13.0 + vFaceId * 0.37)) * step(vSize.y, 9.0) * step(3.0, vSize.y);
        float dx = abs(f.x - vFaceW * 0.5);
        alb = mix(alb, vec3(0.3, 0.3, 0.32), door * fband(dx, 0.0, 2.5, px.x) * fband(f.y, 0.0, 4.0, px.y));
      } else {
        // ---- windows: a grid of cells per style, each window a pulse in both directions
        vec2 cell; vec2 duty; vec2 off = vec2(0.0);
        if (style < 0.5) { cell = vec2(1.6, 3.6); duty = vec2(0.92, 0.86); }          // glass curtain wall
        else if (style < 1.5) { cell = vec2(3.0, 3.6); duty = vec2(0.94, 0.55); }     // office: ribbon windows
        else if (style < 2.5) { cell = vec2(3.2, 3.0); duty = vec2(0.5, 0.55); }      // flats: punched windows
        else { cell = vec2(2.8, 3.4); duty = vec2(0.36, 0.55); }                       // old brick
        // windows start a little above the base and stop below the top
        vec2 q = (f - vec2((vFaceW - floor(vFaceW / cell.x) * cell.x) * 0.5, 0.0)) / cell;
        vec2 qw = px / cell;
        q.y -= 0.15;
        float win = fpulse(q.x - (1.0 - duty.x) * 0.5, duty.x, qw.x) * fpulse(q.y - (1.0 - duty.y) * 0.5, duty.y, qw.y);
        // none on the ground floor of tall buildings (shopfronts instead) or right at the top
        float inside = fband(f.y, 3.6, vSize.y - 0.8, px.y) * fband(f.x, 0.6, vFaceW - 0.6, px.x);
        win *= inside;
        // the glass: dark blue-grey, reflecting the sky
        vec3 r = reflect(-V, n);
        float fres = 0.08 + 0.92 * pow(1.0 - max(dot(V, n), 0.0), 4.0);
        vec3 glass = mix(vec3(0.05, 0.08, 0.11), skyRefl(r), style < 0.5 ? 0.35 + 0.5 * fres : 0.2 + 0.5 * fres);
        // which windows have their lights on (an average of them, once the cells are smaller than a pixel)
        vec2 id = floor(q);
        float far = smoothstep(0.25, 0.8, max(qw.x, qw.y));
        float on = mix(step(hash12(id + seed * 917.0 + vFaceId * 31.0), lit), lit, far);
        float hue = hash12(id * 1.7 + seed * 53.0);
        vec3 lamp = hue < 0.6 ? vec3(1.0, 0.72, 0.42) : hue < 0.85 ? vec3(0.78, 0.9, 1.0) : vec3(1.0, 0.55, 0.8);
        if (style < 0.5) {
          // glass towers are mostly glass: the spandrels between floors are tinted panels
          alb = mix(vCol * 0.55, vCol, 0.5);
        } else if (style > 1.5 && style < 2.5) {
          // flats: a balcony slab under each row of windows
          alb = mix(alb, vCol * 1.12, fband(fract(q.y), 0.0, 0.1, qw.y) * (1.0 - far));
        } else if (style > 2.5) {
          // brick courses
          alb *= 0.9 + 0.1 * fpulse(f.y / 0.3, 0.8, px.y / 0.3);
          // a cornice
          alb = mix(alb, vec3(0.85, 0.8, 0.72), fband(f.y, vSize.y - 1.2, vSize.y - 0.5, px.y));
        }
        // shopfronts: a lit band at street level on taller buildings
        float shop = fband(f.y, 0.4, 3.0, px.y) * step(12.0, vSize.y) * step(vInfo.x, 3.5) * step(0.0, 3.6 - (w.y - f.y - 3.20));
        alb = mix(alb, glass, win);
        spec = win * (style < 0.5 ? 1.0 : 0.5);
        emit += lamp * win * on * (0.25 + 0.75 * uDusk) * 0.9;
        emit += vec3(1.0, 0.8, 0.55) * shop * (0.4 + 0.6 * uDusk) * 0.8;
        alb = mix(alb, vec3(0.12, 0.12, 0.13), shop);
        // the neon trim: a band under the roof line, and up the corners of the glass towers
        if (vNeon >= 0.0) {
          float trim = fband(f.y, vSize.y - 1.4, vSize.y - 0.7, px.y);
          if (style < 0.5) trim = max(trim, (fband(f.x, 0.0, 0.45, px.x) + fband(f.x, vFaceW - 0.45, vFaceW, px.x)) * step(8.0, f.y));
          emit += neonCol * trim * uGlow * (0.6 + 0.4 * uDusk);
          alb = mix(alb, vec3(0.1), trim);
        }
      }
      // dimmer near the foot of every wall: the street's shade
      if (n.y < 0.5) alb *= mix(0.7, 1.0, smoothstep(0.0, 9.0, f.y));
      vec3 c = alb * mapLight(n, w) + emit;
      if (spec > 0.0) {
        vec3 r = reflect(-V, n);
        c += uSunCol * pow(max(dot(r, uSunDir), 0.0), 120.0) * 2.5 * spec * sunShadow(w + n * 3.5) * cloudShade(w.xz);
      }
      gl_FragColor = vec4(c, 1.0);

#include <tonemapping_fragment>
#include <colorspace_fragment>
#ifdef USE_FOG
  gl_FragColor.rgb = mix(gl_FragColor.rgb, uFogOut, 1.0 - exp(-fogDensity * fogDensity * vFogDepth * vFogDepth));
#endif

    }

